/* Paid Blueprint buyer workspace. Every client fact and saved action comes from the server. */
(() => {
  'use strict';
  const host = document.getElementById('blueprint-plan');
  if (!host) return;
  if(new URLSearchParams(location.search).get('demo') === '1'){host.hidden=true;return;}
  const STATES = 'AL:Alabama,AK:Alaska,AZ:Arizona,AR:Arkansas,CA:California,CO:Colorado,CT:Connecticut,DE:Delaware,FL:Florida,GA:Georgia,HI:Hawaii,ID:Idaho,IL:Illinois,IN:Indiana,IA:Iowa,KS:Kansas,KY:Kentucky,LA:Louisiana,ME:Maine,MD:Maryland,MA:Massachusetts,MI:Michigan,MN:Minnesota,MS:Mississippi,MO:Missouri,MT:Montana,NE:Nebraska,NV:Nevada,NH:New Hampshire,NJ:New Jersey,NM:New Mexico,NY:New York,NC:North Carolina,ND:North Dakota,OH:Ohio,OK:Oklahoma,OR:Oregon,PA:Pennsylvania,RI:Rhode Island,SC:South Carolina,SD:South Dakota,TN:Tennessee,TX:Texas,UT:Utah,VT:Vermont,VA:Virginia,WA:Washington,WV:West Virginia,WI:Wisconsin,WY:Wyoming,DC:District of Columbia'.split(',').map(x => x.split(':'));
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = value => value ? new Date(/^\d{4}-\d{2}-\d{2}$/.test(value)?value+'T12:00:00Z':value).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : 'Not set';
  const dollars = cents => cents == null ? 'Not provided' : new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(cents/100);
  const today = () => {const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
  const stateOptions = value => '<option value="">Choose your state</option>'+STATES.map(([code,name])=>`<option value="${code}" ${value===code||value===name?'selected':''}>${name}</option>`).join('');
  const btn = (label,action,primary=false,extra='') => `<button type="button" class="${primary?'bp-primary':''}" data-bp-action="${action}" ${extra}>${label}</button>`;
  const badge = text => `<span class="bp-badge">${esc(text)}</span>`;
  const headers = json => { const h={accept:'application/json'};let token='';try{token=localStorage.getItem('fh_token')||'';}catch{}if(token&&token!=='demo')h.authorization='Bearer '+token;if(json)h['content-type']='application/json';return h; };
  let data=null,view='today',setupStep=0,businessId=null,lessonKey=null,busy=false,loadId=0;
  let newBusinessId=null,helpKey=null,notice='',bankRelationshipId=null,payoffDebtId=null,bankReferenceDraft=null,newPayoffDebtId=null;
  const pendingEvidence = new Map();
  let lettersData=null,lettersState='idle',mailQuote=null,mailOrder=null;const selectedLetters=new Set();
  const plans = () => data?.businessPlans || {};
  const businesses = () => Array.isArray(plans().businesses)?plans().businesses:[];
  const currentBusiness = () => businesses().find(b=>b.id===businessId)||null;
  const lessons = () => {const local=(data?.businessLessons||[]).find(x=>x.planId===businessId);return Array.isArray(local?.lessons)?local.lessons:Array.isArray(data?.lessons)?data.lessons:[];};
  const progress = () => Array.isArray(plans().stepProgress)?plans().stepProgress:[];
  const stepState = (key,id=null) => progress().find(p=>p.stepKey===key&&(p.businessPlanId||null)===(id||null)) || {};
  function safeUrl(value){if(typeof value!=='string'||!value.trim())return null;try{const u=new URL(value,location.origin);return (u.protocol==='https:'||u.origin===location.origin)?u.href:null;}catch{return null;}}
  function message(text){notice=text;const el=host.querySelector('[data-bp-status]');if(el)el.textContent=text;}
  function shell(content){host.innerHTML=`<div class="bp-spread"><div><div class="bp-label">Your 12-month Capital Blueprint</div><h2>${data?.client?.name?'Your next steps, '+esc(String(data.client.name).split(' ')[0])+'.':'Your next steps.'}</h2></div>${badge('Saved to your client file')}</div>${plans().startedAt?`<nav class="bp-tabs" aria-label="Blueprint plan">${[['today','Today'],['businesses','Businesses'],['lessons','Step-by-step help'],['letters','Letters and responses'],['timeline','Timeline'],['support','Get help']].map(([v,t])=>btn(t,'view',false,`data-view="${v}" ${view===v?'aria-current="page"':''}`)).join('')}</nav>`:''}${content}<div class="bp-status" data-bp-status role="status">${esc(notice)}</div><p class="bp-caption bp-end">FinanceOS is not live yet. Your current plan uses saved updates, real documents and available reviews.</p>`;}
  async function request(path,init={}){const r=await fetch(path,{credentials:'same-origin',...init,headers:{...headers(typeof init.body==='string'),...init.headers}});let body;try{body=await r.json();}catch{throw new Error('We couldn’t read the response. Please try again.');}if(!r.ok||body.ok===false){const error=new Error(body.message||'Your change could not be saved. Please try again.');error.status=r.status;error.code=body.error;throw error;}if(path==='/api/blueprint/plan'&&(!body.client||typeof body.client!=='object'||Array.isArray(body.client)||!/^[0-9a-f-]{36}$/i.test(body.businessPlans?.clientId||'')||!/^[0-9a-f-]{36}$/i.test(body.businessPlans?.orgId||'')||!Array.isArray(body.businessPlans?.businesses)))throw new Error('Your saved Blueprint response was incomplete. Please try again.');return body;}
  async function load(){const id=++loadId;document.body.dataset.blueprintPlan='loading';host.hidden=false;host.innerHTML='<div role="status" aria-label="Loading your Blueprint"><div class="bp-skeleton"></div><div class="bp-skeleton large"></div><p class="bp-caption">Loading your saved Blueprint…</p></div>';try{const next=await request('/api/blueprint/plan');if(id!==loadId)return;data=next;host.hidden=false;document.body.dataset.blueprintPlan='active';const generic=document.querySelector('.cp-next-action');if(generic)generic.hidden=true;const money=document.getElementById('money-link');if(money)money.hidden=true;render();}catch(e){if(id!==loadId)return;if([401,403,404].includes(e.status)){host.hidden=true;delete document.body.dataset.blueprintPlan;return;}host.innerHTML=`<h2>Your Blueprint couldn’t load.</h2><p>Your saved progress has not been replaced.</p>${btn('Try again','retry',true)}<p class="bp-status" role="alert">${esc(e.message)}</p>`;}}
  async function save(payload){if(busy)return false;busy=true;host.querySelectorAll('button[type=submit]').forEach(b=>{b.disabled=true;});try{await request('/api/blueprint/business-plans',{method:'POST',body:JSON.stringify(payload)});const next=await request('/api/blueprint/plan');data=next;notice='Saved to your client file.';return true;}catch(e){message(e.message);return false;}finally{busy=false;host.querySelectorAll('button[type=submit]').forEach(b=>{b.disabled=false;});}}
  function navigate(next){view=next;notice='';render();host.scrollIntoView({block:'start',behavior:'smooth'});}
  function render(){if(!data)return;if(!plans().startedAt&&view!=='setup'&&view!=='support')return welcome();if(view==='setup')return setup();const screens={today:dashboard,businesses:businessList,business:businessForm,lessons:lessonList,lesson:lesson,timeline:timeline,letters:letterWorkspace,support:support};(screens[view]||dashboard)();}
  function welcome(){shell(`<div class="bp-grid bp-space"><section><h3>Your Blueprint starts here.</h3><p class="bp-intro">We’ll work on your personal credit and business preparation together. Start with one clear step, then keep your progress in one place.</p><div class="bp-row bp-space">${btn(plans().setupStep?'Continue setup':'Start my plan','start',true)}</div><p class="bp-caption bp-space">We’ll use your existing client file. You won’t need to buy another report just to begin.</p></section><aside class="bp-panel"><h3>What happens first</h3><ol><li>Confirm your starting point.</li><li>Prepare three or four separate businesses over time.</li><li>Follow your next steps and save the evidence.</li></ol><p class="bp-caption">Your documents, ownership history and actual business activity stay separate. We’ll review readiness at the right milestones.</p></aside></div>`);}
  function setup(){const p=plans();const existing=Array.isArray(p.existingBusinesses)?p.existingBusinesses:[];let title,body;if(setupStep===0){title='Do you already own a business?';body=`${existing.length?`<p class="bp-caption">There ${existing.length===1?'is':'are'} ${existing.length} business record${existing.length===1?'':'s'} already on your client file.</p>`:''}<div class="bp-fields">${[['yes','Yes, I already own a business'],['no','No, I’m preparing my first business']].map(([v,t])=>`<label class="bp-choice"><input name="existing" type="radio" value="${v}" ${p.hasExistingBusiness===true&&v==='yes'||p.hasExistingBusiness===false&&v==='no'?'checked':''} required><span>${t}</span></label>`).join('')}</div>`;}else if(setupStep===1){title='How many businesses are we preparing?';body=`<p>Each single-member LLC gets its own plan, documents and timeline.</p><div class="bp-fields">${[3,4].map(n=>`<label class="bp-choice"><input name="count" type="radio" value="${n}" ${(p.targetBusinessCount||3)===n?'checked':''}><span>${n} separate businesses<small>Prepare them over time for the year ahead.</small></span></label>`).join('')}</div>`;}else{title='Where are we building your plan?';body=`<p>Your location helps us choose the right filing instructions and nearby banking candidates.</p><div class="bp-fields"><label class="bp-field">Home state<select name="homeState" required>${stateOptions(p.homeState)}</select></label><label class="bp-field">Home ZIP code<input name="postalCode" value="${esc(p.postalCode||'')}" pattern="[0-9]{5}" inputmode="numeric" maxlength="5" required autocomplete="postal-code"></label></div>`;}shell(`<div class="bp-space"><p class="bp-label">Getting started · ${setupStep+1} of 3</p><h3>${title}</h3><form data-bp-form="setup">${body}<div class="bp-row">${btn('Back','setup-back')}<button type="submit" class="bp-primary">${setupStep===2?'Build my plan':'Save and continue'}</button></div></form></div>`);}
  function nextWaypoint(){const rows=data?.progress?.waypoints||[];const actionable=rows.filter(w=>w.owner==='client'&&['not_started','in_progress','blocked'].includes(w.state)&&!w.completedAt&&w.closedBy!=='ongoing'&&w.verifyKind!=='no_new_credit');return actionable.find(w=>String(w.id)===String(data?.progress?.nextStep?.waypointId))||actionable[0]||null;}
  function nextAction(next){
    if(next?.key!=='blueprint_dispute_mail_letters')return {title:next?.title||'Prepare your first business plan',detail:next?.detail||'Save a basic name, actual business activity and formation state. Then follow the steps for that business.',control:next?'<a class="bp-link bp-primary" href="/progress.html">Open this step →</a>':btn('Plan a business','new-business',true)};
    const readiness=data.letterReadiness?.state;
    if(readiness==='requested')return {title:'Review your mailing request',detail:'Your saved mailing request is in Letters and responses. Check its payment or mailing status before taking another action.',control:btn('Open letters and mailing status','view',true,'data-view="letters"')};
    if(readiness==='ready')return {title:'Review and mail your current letters',detail:'Open your saved letters. Download and mail them yourself, or review the one-time $97 mailing option before authorizing payment.',control:btn('Open my letters','view',true,'data-view="letters"')};
    return {title:readiness==='unavailable'?'Your current letter files couldn’t be checked':'Your current letter pack is not ready yet',detail:'You can prepare your businesses while the letter files are unavailable. Open Letters and responses to check the files, or ask the Fundhub team about an expected letter.',control:btn('Prepare businesses','view',true,'data-view="businesses"')+btn('Check my letters','view',false,'data-view="letters"')};
  }
  function dashboard(){const p=plans(),next=nextWaypoint(),action=nextAction(next),rows=businesses();shell(`<div class="bp-grid bp-space"><section><div class="bp-panel bp-next"><div class="bp-label">Do now</div><h3>${esc(action.title)}</h3><p class="bp-report-detail">${esc(action.detail)}</p>${action.control}</div><div class="bp-space"><h3>Can do alongside this</h3><div class="bp-list"><div class="bp-item"><div class="bp-spread"><div><h3>Your separate businesses</h3><p>${rows.length} of ${p.targetBusinessCount||3} preparation records saved.</p></div>${btn('Open businesses','view',false,'data-view="businesses"')}</div></div><div class="bp-item"><div class="bp-spread"><div><h3>Credit, business and banking lessons</h3><p>Clear actions, useful links, proof and review dates.</p></div>${btn('Find my next steps','view',false,'data-view="lessons"')}</div></div><div class="bp-item"><div class="bp-spread"><div><h3>Your local banking candidates</h3><p>Use your ZIP code, eligibility and available cash to plan the next relationship.</p></div>${btn('Review local banking','lesson',false,'data-key="local_banking"')}</div></div></div></div></section><aside class="bp-stack"><div class="bp-panel"><h3>Your starting information</h3><dl class="bp-facts"><div><dt>Available cash</dt><dd>${dollars(p.availableCashCents)}</dd></div><div><dt>Monthly income</dt><dd>${dollars(p.monthlyIncomeCents)}</dd></div><div><dt>Home ZIP</dt><dd>${esc(p.postalCode||'Not provided')}</dd></div><div><dt>Business target</dt><dd>${p.targetBusinessCount||3} separate plans</dd></div></dl>${btn('Review cash and income','lesson',false,'data-key="budget"')}</div><div class="bp-panel"><h3>Waiting for review</h3><p class="bp-caption">${evidenceSummary()}</p>${btn('View business evidence','view',false,'data-view="businesses"')}</div><div class="bp-panel"><h3>Your credit letters</h3><p class="bp-caption">Download current letters, choose mailing, and upload bureau replies for review.</p>${btn('Open letters and responses','view',false,'data-view="letters"')}</div><div class="bp-notice">A document upload records evidence received. Staff review and a changed credit report are separate checks.</div></aside></div>`);}
  function evidenceSummary(){let count=0;for(const b of businesses())for(const e of Object.values(b.evidence||{}))if(e?.status==='received'||e?.status==='evidence_received')count++;return count?`${count} saved document${count===1?'':'s'} waiting for review.`:'Your submitted business evidence will be tracked here. No evidence is marked reviewed just because time has passed.';}
  function businessList(){const p=plans(),rows=businesses(),existing=p.existingBusinesses||[];shell(`<div class="bp-spread bp-space"><div><h3>Your separate business plans</h3><p class="bp-intro">Plan single-member LLCs with basic names, while keeping the actual facts and dates for each one.</p></div>${rows.length<(p.targetBusinessCount||4)?btn('Add a business plan','new-business',true):rows.length===3?btn('Prepare a fourth business','increase-target'):badge('Four preparation records saved')}</div><div class="bp-businesses bp-space">${rows.map(b=>`<article class="bp-panel"><div class="bp-label">${esc(b.formationStatus==='reported_formed'?'Formation reported':'Planned · not formed')}</div><h3>${esc(b.name)}</h3><p class="bp-caption">${esc(b.activity||'Business activity not provided')}</p><dl class="bp-facts"><div><dt>Formation state</dt><dd>${esc(b.formationState||'Not set')}</dd></div><div><dt>Formation date</dt><dd>${fmt(b.formationDate)}</dd></div><div><dt>Ownership since</dt><dd>${fmt(b.ownershipSince)}</dd></div><div><dt>Operating since</dt><dd>${fmt(b.operatingSince)}</dd></div></dl><div class="bp-space">${btn('Open this business','business',false,`data-id="${esc(b.id)}"`)}</div></article>`).join('')||'<div class="bp-empty"><p>No preparation records yet. Add the first business you want to work on.</p></div>'}</div>${existing.length?`<details class="bp-space"><summary>Businesses already on your file (${existing.length})</summary><div class="bp-list">${existing.map(b=>`<div class="bp-item"><strong>${esc(b.name||b.legal_name||'Existing business')}</strong><p class="bp-caption">Existing company record. A new preparation plan won’t replace it.</p></div>`).join('')}</div></details>`:''}<p class="bp-caption bp-space">Saving a plan does not form an entity or count it as an operating business in UnderwriteIQ.</p>`);}
  function businessForm(){const b=currentBusiness()||{},p=plans(),linked=(p.existingBusinesses||[]).filter(x=>x.id===b.businessId||!businesses().some(plan=>plan.businessId===x.id));shell(`<div class="bp-space"><h3>${b.id?'Your business record':'Plan a separate business'}</h3><div class="bp-grid"><form data-bp-form="business" class="bp-panel"><div class="bp-fields">${linked.length?`<label class="bp-field">Link a business already on your file<select name="businessId"><option value="">Separate new preparation plan</option>${linked.map(x=>`<option value="${esc(x.id)}" ${x.id===b.businessId?'selected':''}>${esc(x.name||'Existing business')}</option>`).join('')}</select></label><p class="bp-caption">Linking keeps its existing company record. Confirm its actual formation date and details before saving.</p>`:''}<label class="bp-field">Basic business name<input name="name" value="${esc(b.name||'')}" required maxlength="120" placeholder="Enter your chosen name"></label><label class="bp-field">Actual business activity<textarea name="activity" required maxlength="1500" rows="3" placeholder="What product or service will this business provide?">${esc(b.activity||'')}</textarea></label><label class="bp-field">Formation state<select name="formationState" required>${stateOptions(b.formationState||p.homeState)}</select></label><label class="bp-field">Operating state, if known<select name="operatingState">${stateOptions(b.operatingState)}</select></label><label class="bp-field">Website, if available<input name="website" type="url" maxlength="250" value="${esc(b.website||'')}" placeholder="https://your-business.com"></label><label class="bp-field">Current formation status<select name="formationStatus"><option value="planned" ${b.formationStatus!=='reported_formed'?'selected':''}>Planned · not formed</option><option value="reported_formed" ${b.formationStatus==='reported_formed'?'selected':''}>I report that it is formed</option></select></label><label class="bp-field">Actual formation date, if formed<input name="formationDate" type="date" max="${today()}" value="${esc(b.formationDate||'')}"></label><label class="bp-field">Your ownership began<input name="ownershipSince" type="date" max="${today()}" value="${esc(b.ownershipSince||'')}"></label><label class="bp-field">Actual operations began, if operating<input name="operatingSince" type="date" max="${today()}" value="${esc(b.operatingSince||'')}"></label></div><div class="bp-row"><button type="submit" class="bp-primary">Save business plan</button>${btn('Back to businesses','view',false,'data-view="businesses"')}</div></form><aside class="bp-stack"><div class="bp-notice">Start with a single-member LLC plan. Later tax elections are a separate decision. Formation age, ownership history and operating history stay distinct.</div>${b.id?`<section class="bp-panel"><h3>This business’s documents</h3>${evidenceForm(b,'formation','Formation document','articles_of_organization')}${evidenceForm(b,'ein','EIN confirmation','ein_letter')}</section><section class="bp-panel"><h3>Business preparation</h3><div class="bp-stack">${['formation','ein','business_profile','business_website','bank_opening','bank_deposit'].map(key=>btn(lessons().find(l=>l.key===key)?.title||key.replaceAll('_',' '),'lesson',false,`data-key="${key}" data-business="${esc(b.id)}"`)).join('')}</div></section>`:'<div class="bp-panel"><h3>Then follow the steps</h3><p class="bp-caption">After saving the basics, you can open its formation and EIN lessons and attach real documents.</p></div>'}</aside></div></div>`);}
  function evidenceForm(b,kind,title,subtype){const available=(plans().availableEvidence||[]).filter(x=>x.kind===kind&&(!x.entityId||x.entityId===b.entityId));const recovery=available.length?`<form data-bp-form="saved-evidence" data-business="${esc(b.id)}" data-kind="${kind}"><label class="bp-field">Use a file already on your record<select name="documentId" required><option value="">Choose the correct saved file for this business</option>${available.map(x=>`<option value="${esc(x.documentId)}">${esc(x.filename)} · ${fmt(x.receivedAt)}</option>`).join('')}</select></label><button type="submit">Attach saved document</button><p class="bp-caption">If a previous upload succeeded, attach its stored file here to avoid uploading it again.</p></form>`:'';const e=b.evidence?.[kind]||{};const status={not_added:'Not added',received:'Evidence received',evidence_received:'Evidence received',reviewed:'Reviewed by the team',accepted:'Accepted after review',rejected:'Needs attention',unavailable:'Needs business assignment review'}[e.status]||e.status||'Not added';return `<div class="bp-summary"><strong>${title}</strong><p class="bp-caption">${esc(status)}${e.reviewedAt?' · '+fmt(e.reviewedAt):''}</p>${e.documentId?btn('Open saved document','open-document',false,`data-id="${esc(e.documentId)}"`):''}${kind==='ein'&&!b.evidence?.formation?.documentId?'<p class="bp-caption">Add the formation document before uploading this business’s EIN letter.</p>':`${recovery}<form data-bp-form="evidence" data-kind="${kind}" data-subtype="${subtype}" data-business="${esc(b.id)}"><label class="bp-field">${e.documentId?'Add replacement document':'Choose document'}<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.heic" ${pendingEvidence.has(b.id+':'+kind)?'':'required'}></label>${pendingEvidence.has(b.id+':'+kind)?'<p class="bp-caption">Your upload is stored. Retry attaching it to this business without choosing another file.</p>':''}<button type="submit">${pendingEvidence.has(b.id+':'+kind)?'Retry attaching stored document':'Upload '+(kind==='ein'?'EIN confirmation':'formation document')}</button></form>`}</div>`;}
  function lessonList(){const grouped={};for(const l of lessons())(grouped[l.track||'Your preparation']??=[]).push(l);shell(`<div class="bp-space"><h3>Know how to take each step.</h3><p class="bp-intro">Use the lessons relevant to your file. Save a status, a question or a review date as you go.</p>${Object.entries(grouped).map(([track,rows])=>`<section class="bp-space"><h3>${esc(track)}</h3><div class="bp-list">${rows.map(l=>`<div class="bp-item"><div class="bp-spread"><div><h3>${esc(l.title)}</h3><p>${esc(l.why)}</p>${badge(l.applicability==='review_needed'?'Review your file first':l.optional?'Optional step':stepState(l.key).status==='reported_complete'?'You reported complete':'Available to work on')}</div>${btn('Open step','lesson',false,`data-key="${esc(l.key)}"`)}</div></div>`).join('')}</div></section>`).join('')}</div>`);}
  function lesson(){const l=lessons().find(x=>x.key===lessonKey);if(!l)return lessonList();const b=currentBusiness();const saved=stepState(l.key,businessId);const businessTopics=['formation','ein','business_profile','business_website','business_listings','bank_opening','bank_deposit','business_credit','merchant_tools'];const perBusiness=businessTopics.includes(l.key);shell(`<div class="bp-space"><div class="bp-label">${esc(l.track||'Your next step')}</div><h3>${esc(l.title)}</h3><div class="bp-grid"><section class="bp-panel"><p>${esc(l.why)}</p>${l.applicability==='review_needed'?'<div class="bp-notice">Review your actual file before choosing this action. This lesson does not mean you need a new account or an authorized-user removal.</div>':''}${perBusiness?`<label class="bp-field bp-space">Business for this step<select data-bp-business><option value="">Choose a business plan</option>${businesses().map(x=>`<option value="${esc(x.id)}" ${x.id===businessId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}<ol>${(l.steps||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="bp-links">${(l.links||[]).map(link=>{const url=safeUrl(link.url);return url?`<a class="bp-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(link.label)} ↗</a>`:'';}).join('')}</div>${l.key==='business_website'?`<div class="bp-prompt" id="bp-website-prompt">${esc((data.websitePrompts||[]).find(x=>x.planId===businessId)?.prompt||websiteText(b))}</div>${btn('Copy website prompt','copy-prompt')}`:''}${l.key==='local_banking'?bankCandidates():''}${l.key==='budget'?budgetForm():''}${l.key==='bank_opening'||l.key==='bank_deposit'?bankPlan():''}${l.key==='formation'||l.key==='ein'?`<p class="bp-caption">${b?'Add the document to this business’s record when the step is ready.':'Save a business plan first so its documents stay with the right business.'}</p>${btn(b?'Open this business’s documents':'Open business plans',b?'business':'view',false,b?`data-id="${esc(b.id)}"`:'data-view="businesses"')}`:''}</section><aside class="bp-stack"><div class="bp-panel"><h3>How this step is checked</h3><p class="bp-caption">${esc(l.proof||'Save your update and attach the relevant evidence when available.')}</p><p class="bp-caption">${esc(l.nextReview||'Review the saved result at your next check-in.')}</p></div><form data-bp-form="step" class="bp-panel"><h3>Save your progress</h3><div class="bp-fields"><label class="bp-field">Your update<select name="status">${[['not_started','Not started'],['in_progress','In progress'],['reported_complete','I report this complete'],['blocked','I need help with this step']].map(([v,t])=>`<option value="${v}" ${saved.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="bp-field">Next review date<input type="date" name="targetDate" value="${esc(saved.targetDate||'')}"></label><label class="bp-field">Notes or questions<textarea name="note" maxlength="1500" rows="3">${esc(saved.note||'')}</textarea></label></div><button type="submit" class="bp-primary">Save this step</button><p class="bp-caption bp-space">Your report is saved as your update. It does not replace a document review or credit-report result.</p></form>${btn('Ask the Fundhub team','help')}<p class="bp-caption">${l.optional?'This is optional. It is not a requirement for every client.':''}</p></aside></div></div>`);}
  function websiteText(b){return `Write a clear website for ${b?.name||'[business name]'}. Actual business activity: ${b?.activity||'[actual product or service]'}. Include services, who we serve, about and contact information. Match my real business records. Ask for missing details. Do not invent credentials, revenue, history or testimonials.`;}
  function bankCandidates(){const result=data.localBanks||{},rows=result.candidates||[];return `<section class="bp-space"><h3>Local credit-union candidates</h3><p class="bp-caption">${esc(result.source?.name||result.source||'Official credit-union branch directory')}${result.asOf||result.source?.asOf?' · Source date '+esc(result.asOf||result.source?.asOf):''}. Membership, accounts and deposit fit still need review.</p>${rows.length?`<div class="bp-list">${rows.slice(0,5).map(r=>`<div class="bp-item"><strong>${esc(r.name||r.creditUnionName||r.institutionName)}</strong><p>${esc([r.branch?.address||r.address||r.street,r.branch?.city||r.city,r.branch?.state||r.state,r.branch?.postalCode||r.zip||r.postalCode].filter(Boolean).join(', '))}</p><p class="bp-caption">${esc(r.distanceLabel||r.matchLabel||'Local branch candidate')} · Membership and account fit need review</p>${(r.website||r.locatorUrl)&&safeUrl(r.website||r.locatorUrl)?`<a class="bp-link" href="${esc(safeUrl(r.website||r.locatorUrl))}" target="_blank" rel="noopener noreferrer">Review this credit union ↗</a>`:''}</div>`).join('')}</div>`:'<p class="bp-notice">No verified local matches are available for the saved location. Review your state and ZIP code, then use the official locator in this lesson.</p>'}</section>`;}
  function budgetForm(){const p=plans(),c=data.cashPlan;return `<form data-bp-form="budget" class="bp-space"><h3>Your cash and income plan</h3><p class="bp-caption">Use current amounts you can support. One-time cash commitments and your monthly debt-payment budget are separate.</p><div class="bp-fields">${[['cash','Cash available for the plan, USD',p.availableCashCents],['income','Monthly income, USD',p.monthlyIncomeCents],['buffer','Cash to leave untouched for bills and a buffer, USD',p.cashBufferCents],['payoffReserve','One-time cash reserved for credit paydowns, USD',p.oneTimePayoffCents]].map(([name,label,value])=>`<label class="bp-field">${label}<input type="number" name="${name}" min="0" step="0.01" max="10000000" value="${value==null?'':value/100}"></label>`).join('')}</div><button type="submit">Save cash and income</button>${c?`<div class="bp-notice bp-space">Saved bank deposit commitments: ${dollars(c.bankDepositTotalCents)}. ${c.status==='review_needed'?'Add the unknown cash, buffer, paydown and deposit amounts before treating any cash as free to commit.':c.status==='overcommitted'?'These plans exceed your reported cash by '+dollars(-c.remainingCashCents)+'. Adjust the commitments before moving money.':'Cash left after these commitments: '+dollars(c.remainingCashCents)+'.'}</div>`:''}</form>${payoffForm()}`;}
  function payoffForm(){const saved=plans().payoffPlan||{},rows=saved.debts||[],d=rows.find(x=>x.id===payoffDebtId)||{},calculation=data.payoffCalculation;
    const moneyInput=(name,label,value)=>`<label class="bp-field">${label}<input name="${name}" type="number" min="0" step="0.01" value="${value==null?'':value/100}"></label>`;
    return `<section class="bp-space"><h3>Your debt-payoff order</h3><p>Keep the required minimum payments on your accounts. Snowball focuses extra money on the smallest balance; highest-interest-first focuses it on the largest APR. Check your current UnderwriteIQ step before choosing a different credit priority.</p><form data-bp-form="payoff-settings"><div class="bp-fields"><label class="bp-field">Your chosen approach<select name="strategy"><option value="snowball" ${saved.strategy!=='avalanche'?'selected':''}>Snowball · smallest balance first</option><option value="avalanche" ${saved.strategy==='avalanche'?'selected':''}>Highest interest first</option></select></label>${moneyInput('monthlyBudget','Total monthly debt-payment budget, including minimums, USD',saved.monthlyBudgetCents)}</div><button type="submit">Save payoff approach</button></form>
    ${calculation?`<div class="bp-notice bp-space">${calculation.status==='ready'?'Monthly payments planned: '+dollars(calculation.allocatedCents)+'. Unused monthly budget: '+dollars(calculation.unallocatedCents)+'.':calculation.status==='minimum_shortfall'?'Your monthly budget is short of known minimums by '+(calculation.requiredMinimumTotalCents==null?'at least ':'')+dollars(calculation.minimumShortfallCents)+'. Ask the team for help before planning extra payments.':'Add the missing monthly budget, minimum payments'+(saved.strategy==='avalanche'?' and interest rates':'')+' to calculate a payment plan.'} No payment is sent by saving this plan.</div>`:''}
    <div class="bp-list bp-space">${(calculation?.debts||rows).map(x=>`<div class="bp-item"><strong>${x.priorityRank?'Priority '+x.priorityRank+' · ':''}${esc(x.label)}</strong><p>Balance ${dollars(x.balanceCents)} · APR ${x.aprBps==null?'Unknown':esc(x.aprBps/100)+'%'} · Minimum ${dollars(x.minimumPaymentCents)}</p>${x.allocationCents!=null?`<p>Planned monthly payment: ${dollars(x.allocationCents)} (${dollars(x.extraAllocationCents)} above the minimum).</p>`:''}<div class="bp-row">${btn('Edit debt','edit-debt',false,`data-id="${esc(x.id)}"`)}${btn('Remove from payoff plan','remove-debt',false,`data-id="${esc(x.id)}"`)}</div></div>`).join('')}</div>
    ${rows.length<20||d.id?`<form data-bp-form="payoff-debt" class="bp-space"><h3>${d.id?'Update this debt':'Add a current debt'}</h3><p class="bp-caption">Use a recent statement. Add a label, without account numbers. Leave an unknown rate or minimum blank.</p><div class="bp-fields"><label class="bp-field">Debt label<input name="label" maxlength="120" required value="${esc(d.label||'')}"></label>${moneyInput('balance','Current balance, USD',d.balanceCents)}<label class="bp-field">APR, percent<input name="apr" type="number" min="0" max="1000" step="0.01" value="${d.aprBps==null?'':d.aprBps/100}"></label>${moneyInput('minimum','Required minimum payment, USD',d.minimumPaymentCents)}</div><button type="submit">Save debt details</button></form>`:''}<p class="bp-caption bp-space">This is a plan from your reported balances and current terms. It does not estimate a payoff date, future interest or credit-score change. Keep bills, your buffer and bank deposit commitments funded.</p></section>`;
  }
  function bankPlan(){
    const b=currentBusiness(),p=plans(),raw=data.bankPlan;
    const rows=b?.bankPreparation?.relationships||[];
    const r=rows.find(x=>x.id===bankRelationshipId)||bankReferenceDraft||{};
    const all=businesses().flatMap(x=>x.bankPreparation?.relationships||[]);
    const known=all.filter(x=>x.depositPlanCents!=null);
    const planned=known.reduce((n,x)=>n+x.depositPlanCents,0);
    const references=Array.isArray(raw?.recommended_banks)?raw.recommended_banks.slice(0,5):[];
    return `<section class="bp-space"><h3>Plan and record the relationship</h3><p>Start with one to three suitable accounts at a pace your cash and circumstances support. Each saved record belongs to one business.</p><p class="bp-caption">Your reported cash: ${dollars(p.availableCashCents)}. Your reported monthly income: ${dollars(p.monthlyIncomeCents)}.</p>${known.length?`<div class="bp-notice">Planned deposits across all businesses: ${dollars(planned)}. ${data.cashPlan?.status==='overcommitted'?'The saved deposits, buffer and one-time paydowns exceed your cash by '+dollars(-data.cashPlan.remainingCashCents)+'. Adjust the commitments before moving money.':data.cashPlan?.status==='review_needed'?'Cash fit is not ready: add the missing buffer, paydown or deposit amounts in your cash plan.':'Keep paydowns, business costs, bills and your buffer in the same cash plan. Cash left after saved commitments: '+dollars(data.cashPlan?.remainingCashCents)+'.'}</div>`:''}
    ${references.length?`<details><summary>Existing lender relationship guidance</summary><div class="bp-list">${references.map((x,index)=>`<div class="bp-item"><strong>${esc(x.name)}</strong><p>${esc((x.products||[]).join(', '))}</p><p class="bp-caption">Planning deposit reference: ${dollars(x.minimum_deposit_cents)} · Seasoning reference: ${x.seasoning_days==null?'Not provided':esc(x.seasoning_days)+' days'}.</p><p class="bp-caption">Saved lender notes are a planning reference. Confirm the current account, eligibility, fees and requirements before applying.</p>${(x.relationship_steps||[]).map(step=>`<p class="bp-caption">${esc(step.text)}</p>`).join('')}<p class="bp-caption">${({within_reported_budget:'The saved deposit reference fits your remaining reported cash budget.',exceeds_remaining_budget:'The saved deposit reference exceeds your remaining reported cash budget.',review_needed:'Cash fit needs the missing amounts and current bank terms reviewed.'})[(data.cashPlan?.banks||[]).find(r=>r.name===x.name)?.cashFit||'review_needed']}</p>${b&&rows.length<3?btn('Plan this relationship','bank-reference',false,`data-index="${index}"`):''}</div>`).join('')}</div></details>`:'<p class="bp-caption">Existing lender guidance is not available yet. You can still save the preparation and ask the team to review account fit.</p>'}
    ${b?`<form data-bp-form="bank-readiness" class="bp-space"><h3>Before opening an account</h3><label class="bp-choice"><input type="checkbox" name="documentsReady" ${b.bankPreparation?.documentsReady?'checked':''}><span>I have the required identity and business documents ready.</span></label><label class="bp-choice"><input type="checkbox" name="accountOpeningIssue" ${b.bankPreparation?.accountOpeningIssue?'checked':''}><span>I ran into an account-opening issue and need help reviewing it.</span></label><button type="submit">Save banking readiness</button><p class="bp-caption">If there is an issue, use the ChexSystems lesson to request your own report, check errors and save a question for the team.</p></form><div class="bp-list bp-space">${rows.map(x=>`<div class="bp-item"><strong>${esc(x.bankName)}</strong><p class="bp-caption">${esc(x.status.replaceAll('_',' '))} · Planned deposit ${dollars(x.depositPlanCents)} · Opening ${fmt(x.openedOn||x.plannedOpenOn)} · Next review ${fmt(x.nextReviewOn)}</p>${btn('Edit this relationship','edit-bank',false,`data-id="${esc(x.id)}"`)}</div>`).join('')}</div>${rows.length<3||r.id?`<form data-bp-form="bank-relationship" class="bp-space"><h3>${r.id?'Update this relationship':'Add a bank relationship plan'}</h3><div class="bp-fields"><label class="bp-field">Bank or credit union name<input name="bankName" required maxlength="120" value="${esc(r.bankName||'')}"></label><label class="bp-field">Account type<select name="accountType">${[['business_checking','Business checking'],['personal_checking','Personal checking'],['savings','Savings']].map(([v,t])=>`<option value="${v}" ${r.accountType===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="bp-field">Current status<select name="status">${[['planned','Planned'],['reported_open','I report it opened'],['reported_funded','I report it opened and funded']].map(([v,t])=>`<option value="${v}" ${r.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="bp-field">Planned opening date<input name="plannedOpenOn" type="date" value="${esc(r.plannedOpenOn||'')}"></label><label class="bp-field">Actual opening date, if opened<input name="openedOn" type="date" max="${today()}" value="${esc(r.openedOn||'')}"></label><label class="bp-field">Planned deposit, USD<input name="depositPlan" type="number" min="0" step="0.01" value="${r.depositPlanCents==null?'':r.depositPlanCents/100}"></label><label class="bp-field">Deposit you report making, USD<input name="depositReported" type="number" min="0" step="0.01" value="${r.depositReportedCents==null?'':r.depositReportedCents/100}"></label><label class="bp-field">Actual deposit date, if deposited<input name="depositedOn" type="date" max="${today()}" value="${esc(r.depositedOn||'')}"></label><label class="bp-field">Seasoning days in your reviewed plan<input name="seasoningDays" type="number" min="0" max="730" step="1" value="${r.seasoningDays??''}"></label><label class="bp-field">Next review date<input name="nextReviewOn" type="date" value="${esc(r.nextReviewOn||'')}"></label></div><button type="submit">Save bank relationship</button><p class="bp-caption bp-space">These are your reported updates. No bank account is opened, funded or verified by saving this form.</p></form>`:'<p class="bp-caption">Three relationship plans saved for this business. Review them before adding more.</p>'}`:'<p class="bp-notice">Choose a saved business plan above before recording its banking milestones.</p>'}</section>`;
  }
  function addMonths(value,count){const d=new Date(value.slice(0,10)+'T12:00:00Z'),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+count);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10);}
  function timelineRows(){
    const rows=progress().filter(p=>p.targetDate).map(p=>({id:'step:'+p.stepKey+':'+(p.businessPlanId||''),date:p.targetDate,title:(data.lessons||[]).find(l=>l.key===p.stepKey)?.title||p.stepKey,subject:businesses().find(b=>b.id===p.businessPlanId)?.name||'Your personal plan',status:p.status||'not_started'}));
    for(const b of businesses()){
      if(b.formationDate)for(const months of[3,6,12])rows.push({id:'formation:'+b.id+':'+months,date:addMonths(b.formationDate,months),title:months+'-month business preparation review',subject:b.name,status:'Review actual activity, records and readiness. Formation age alone does not establish eligibility.'});
      for(const r of b.bankPreparation?.relationships||[]){
        if(r.nextReviewOn)rows.push({id:'bank:'+b.id+':'+r.id,date:r.nextReviewOn,title:'Review '+r.bankName+' relationship',subject:b.name,status:'Review your reported bank milestones and current account requirements.'});
        if(r.depositedOn&&r.seasoningDays!=null){const d=new Date(r.depositedOn+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+r.seasoningDays);const date=d.toISOString().slice(0,10);if(date!==r.nextReviewOn)rows.push({id:'seasoning:'+b.id+':'+r.id,date,title:'Check '+r.bankName+' seasoning plan',subject:b.name,status:'Calculated from your reported deposit date and reviewed seasoning days. Confirm the actual result before applying.'});}
      }
    }
    return rows.sort((a,b)=>a.date.localeCompare(b.date));
  }
  function timeline(){const rows=timelineRows();shell(`<section class="bp-space"><h3>Your saved review dates</h3><p class="bp-intro">Saved step dates, bank reviews and business preparation milestones appear together. Dates are reminders to review the result. They never mark work complete.</p>${rows.length?`<div class="bp-timeline">${rows.map(p=>`<article><div class="bp-label">${fmt(p.date)}</div><h3>${esc(p.title)}</h3><p class="bp-caption">${esc(p.subject)} · ${esc(p.status)}</p><div class="bp-links"><a class="bp-link" href="${esc(googleCalendar(p))}" target="_blank" rel="noopener noreferrer">Add to Google Calendar ↗</a>${btn('Download calendar file','calendar',false,`data-calendar-id="${esc(p.id)}"`)}</div></article>`).join('')}</div>`:'<div class="bp-empty"><p>No review dates saved yet. Open a step and choose its next review date.</p>'+btn('Choose a step','view',true,'data-view="lessons"')+'</div>'}<p class="bp-caption">Google Calendar opens with your review details. Save the event there to add reminders. This is not automatic two-way synchronization.</p></section>`);}
  function datePair(value){const start=value.replaceAll('-',''),d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);return[start,d.toISOString().slice(0,10).replaceAll('-','')];}
  function googleCalendar(p){const [s,e]=datePair(p.date);const q=new URLSearchParams({action:'TEMPLATE',text:'Blueprint: '+p.title,dates:s+'/'+e,details:'Review saved progress for '+p.subject+'. Open your Fundhub portal to review evidence and next steps.'});return 'https://calendar.google.com/calendar/render?'+q;}
  async function loadLetters(){lettersState='loading';render();try{lettersData=await request('/api/blueprint/letter-mailing');lettersState='ready';selectedLetters.clear();for(const l of lettersData.letters||[])if(l.eligibleForMailing)selectedLetters.add(l.documentId);if(view==='letters')render();}catch(e){lettersState='error';notice=e.message;if(view==='letters')render();}}
  function letterWorkspace(){if(lettersState==='idle'){void loadLetters();return;}const rows=lettersData?.letters||[];const responses=data.letterResponses;const orders=mailOrder?[mailOrder,...(lettersData?.orders||[]).filter(o=>o.id!==mailOrder.id)]:lettersData?.orders||[];
    shell(`<section class="bp-space"><h3>Your letters, mailing and responses</h3><p class="bp-intro">We prepare letters from your current file. You choose to send them yourself or have Fundhub print and mail the selected batch for $97. Upload the replies you receive so the team can review the next step.</p>
      ${lettersState==='loading'?'<div class="bp-skeleton large" role="status" aria-label="Loading your letters"></div>':lettersState==='error'?`<p class="bp-error">Your saved letters could not load. Your files have not been replaced.</p>${btn('Retry loading letters','reload-letters')}`:rows.length?`<div class="bp-list">${rows.map(l=>`<article class="bp-item"><div class="bp-spread"><div><strong>${esc(l.title||'Saved credit letter')}</strong><p class="bp-caption">${esc(l.bureau||'Recipient listed in letter')} · ${fmt(l.generatedAt)}</p>${l.eligibleForMailing?`<label class="bp-check"><input type="checkbox" data-mail-letter="${esc(l.documentId)}" ${selectedLetters.has(l.documentId)?'checked':''}>Include in this mailing batch</label>`:`<p class="bp-caption">${esc(l.reason||'Review needed before mailing')}</p>`}</div>${btn('Download letter','open-document',false,`data-id="${esc(l.documentId)}"`)}</div></article>`).join('')}</div>${lettersData.capabilities?.mailSupported?`<div class="bp-row bp-space">${btn('Mail these letters for me · $97','quote-mail',true)}</div><p class="bp-caption bp-space">Review the selected letters, return address and payment method before confirming. No recurring mailing charge.</p>`:`<p class="bp-notice">Mailing service needs setup before payment can be taken. You can download your letters and follow the self-mailing steps below.</p>`}`:'<p class="bp-notice">No current generated letters are available here yet. Letters are created when your current file calls for them. Ask the team if an expected letter is missing.</p>'}
      ${mailQuote?`<form data-bp-form="mail-confirm" class="bp-panel bp-space"><h3>Review your $97 mailing batch</h3><p>${(mailQuote.items||[]).length} selected letter(s) · Total ${dollars(mailQuote.totalCents)} ${esc(mailQuote.currency)}</p><ul>${(mailQuote.items||[]).map(x=>`<li>${esc(x.title||'Saved letter')} · ${esc(x.bureau||'')}</li>`).join('')}</ul><p>Return address: ${esc([mailQuote.returnAddressSummary?.name,mailQuote.returnAddressSummary?.line1,mailQuote.returnAddressSummary?.city,mailQuote.returnAddressSummary?.state,mailQuote.returnAddressSummary?.postalCode].filter(Boolean).join(', '))}</p><div class="bp-fields"><label class="bp-field">Payment method<select name="paymentOptionId" required>${(mailQuote.paymentOptions||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('')}</select></label><label class="bp-choice"><input name="authorization" type="checkbox" required><span>I reviewed these letters and authorize Fundhub to charge $97 once and mail this selected batch on my behalf.</span></label></div><button type="submit" class="bp-primary">Confirm $97 and mail my letters</button></form>`:''}
      ${orders.length?`<section class="bp-space"><h3>Your mailing requests</h3><div class="bp-list">${orders.map(o=>`<article class="bp-item"><strong>${dollars(o.totalCents)} · ${esc(o.status==='mailed'?'Submitted for mailing':String(o.status||'pending').replaceAll('_',' '))}</strong><p class="bp-caption">Payment, mailing acceptance and delivery are separate statuses.</p>${(o.envelopes||[]).map(e=>`<p>${esc(e.bureau)} · ${esc(e.status)} ${safeUrl(e.trackingUrl)?`<a class="bp-link" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(e.trackingUrl))}">Track mailing</a>`:''}</p>`).join('')}<div class="bp-row">${btn('Check request status','mail-status',false,`data-id="${esc(o.id)}"`)}${safeUrl(o.checkoutUrl)?`<a class="bp-link" href="${esc(safeUrl(o.checkoutUrl))}">Continue secure payment</a>`:''}</div></article>`).join('')}</div></section>`:''}
      <details class="bp-space"><summary>How to send the letters yourself</summary><ol><li>Download each current letter. Check your identity, recipient and the information it asks to correct. Ask the team about anything inaccurate or unclear.</li><li>Follow the instructions included with that letter. Sign and date where required; include copies of the requested supporting records.</li><li>Keep a copy of your packet. Send it to the current recipient address specified in your instructions. Tracking or certified mail with a return receipt helps preserve delivery evidence.</li><li>Upload your mailing proof in View progress. Upload bureau replies below when you receive them.</li><li>Wait for the document review and next instruction. Uploading a file alone does not verify a credit change or automatically justify another round.</li></ol><div class="bp-links"><a class="bp-link" href="/progress.html">Upload mailing proof in View progress</a><a class="bp-link" href="https://www.consumerfinance.gov/ask-cfpb/how-do-i-dispute-an-error-on-my-credit-report-en-314/" target="_blank" rel="noopener noreferrer">Review official dispute instructions</a></div></details>
      <section class="bp-panel bp-space"><h3>Upload a bureau response</h3><p>Upload the actual reply you received, including all relevant pages. Use a clear PDF or photos, with the bureau, date, your details and response text readable.</p><form data-bp-form="bureau-response"><label class="bp-field">Actual bureau reply<input name="files" type="file" accept=".pdf,.png,.jpg,.jpeg,.heic" multiple required></label><button type="submit">Upload response for validation</button></form><p class="bp-caption bp-space">Received files go through the existing document reader. Unclear, mismatched or questionable files stay open for review. An accepted document is separate from a verified credit-report change.</p></section>
      <section class="bp-space"><h3>Your uploaded replies</h3>${responses===null?'<p class="bp-error">Response review status could not load. Refresh before relying on it.</p>':(responses||[]).length?`<div class="bp-list">${responses.map(r=>`<article class="bp-item"><strong>${esc(r.title)}</strong><p>${({accepted:'Document accepted for review of the next step',request_more:'A clearer or more complete file is needed',hold:'Team review required',pending:'Received · validation pending'})[r.validationStatus]||'Received · validation pending'}</p>${r.reason?`<p class="bp-caption">${esc(r.reason)}</p>`:''}${btn('Open uploaded reply','open-document',false,`data-id="${esc(r.documentId)}"`)}</article>`).join('')}</div>`:'<p class="bp-caption">Your submitted replies will appear here with their saved review state.</p>'}${btn('Refresh letters and reviews','refresh-letter-reviews')}</section>
    </section>`);
  }
  function support(){shell(`<section class="bp-space"><h3>Ask about your current step.</h3><p class="bp-intro">Your message is saved in your existing Fundhub conversation, so the team can follow the same client file.</p><form data-bp-form="help" class="bp-panel bp-space"><label class="bp-field">What are you working on, and what is getting in the way?<textarea name="message" required maxlength="1500" rows="4"></textarea></label><div class="bp-row bp-space"><button type="submit" class="bp-primary">Send to my Fundhub conversation</button></div></form></section>`);}
  function failed(form,text){let el=form.querySelector('[data-form-error]');if(!el){el=document.createElement('p');el.className='bp-error bp-space';el.dataset.formError='';el.setAttribute('role','alert');form.append(el);}el.textContent=text;}
  host.addEventListener('change',async e=>{if(e.target.matches('[data-mail-letter]')){const id=e.target.dataset.mailLetter;e.target.checked?selectedLetters.add(id):selectedLetters.delete(id);if(mailQuote){mailQuote=null;notice='Your selection changed. Review a new quote before paying.';render();}return;}if(e.target.matches('select[name=businessId]')){const b=(plans().existingBusinesses||[]).find(x=>x.id===e.target.value);if(!b)return;const form=e.target.form;for(const key of['name','activity','formationState','operatingState','formationDate','ownershipSince','operatingSince'])if(b[key]!=null&&form.elements[key])form.elements[key].value=b[key];form.elements.formationStatus.value='reported_formed';return;}if(e.target.matches('[data-bp-business]')){businessId=e.target.value||null;bankRelationshipId=null;render();}});
  host.addEventListener('click',async e=>{const el=e.target.closest('[data-bp-action]');if(!el||busy)return;const action=el.dataset.bpAction;
    if(action==='edit-bank'){bankReferenceDraft=null;bankRelationshipId=el.dataset.id;return render();}
    if(action==='bank-reference'){const bank=data.bankPlan?.recommended_banks?.[Number(el.dataset.index)];if(!bank)return;bankRelationshipId=null;bankReferenceDraft={bankName:bank.name,accountType:'business_checking',status:'planned',depositPlanCents:bank.minimum_deposit_cents??null,seasoningDays:bank.seasoning_days??null};return render();}
    if(action==='edit-debt'){payoffDebtId=el.dataset.id;return render();}
    if(action==='remove-debt'){const p=plans().payoffPlan;if(!p)return;if(await save({action:'save_payoff_plan',...p,debts:p.debts.filter(d=>d.id!==el.dataset.id)})){payoffDebtId=null;render();}return;}
    if(action==='open-document'){const win=window.open('about:blank','_blank');if(win)win.opener=null;try{const saved=await request('/api/documents-download?id='+encodeURIComponent(el.dataset.id));const candidate=saved.document?.download;const url=safeUrl(typeof candidate==='string'?candidate:candidate?.url);if(!url)throw Error('The saved document does not have an available download link.');if(win)win.location.replace(url);else{const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.className='bp-link';a.textContent='Open your saved document';host.querySelector('[data-bp-status]').replaceChildren(a);}}catch(err){if(win)win.close();message(err.message);}return;}
    if(action==='reload-letters')return loadLetters();
    if(action==='refresh-letter-reviews'){try{data=await request('/api/blueprint/plan');await loadLetters();}catch(err){message(err.message);}return;}
    if(action==='quote-mail'){if(!selectedLetters.size)return message('Choose the current letters you want Fundhub to mail.');busy=true;try{mailQuote=await request('/api/blueprint/letter-mailing',{method:'POST',body:JSON.stringify({action:'quote',documentIds:[...selectedLetters]})});render();}catch(err){message(err.message);}finally{busy=false;}return;}
    if(action==='mail-status'){busy=true;try{const reply=await request('/api/blueprint/letter-mailing',{method:'POST',body:JSON.stringify({action:'status',orderId:el.dataset.id})});mailOrder=reply.order||reply;render();}catch(err){message(err.message);}finally{busy=false;}return;}
    if(action==='retry')return load();
    if(action==='view')return navigate(el.dataset.view);
    if(action==='start'){view='setup';setupStep=Math.min(2,Number(plans().setupStep)||0);return render();}
    if(action==='setup-back'){if(setupStep===0){view='today';return welcome();}setupStep--;return render();}
    if(action==='increase-target'){if(await save({action:'save_settings',targetBusinessCount:4})){businessId=null;newBusinessId=crypto.randomUUID();navigate('business');}return;}
    if(action==='new-business'){businessId=null;newBusinessId=crypto.randomUUID();return navigate('business');}
    if(action==='business'){businessId=el.dataset.id;newBusinessId=null;return navigate('business');}
    if(action==='lesson'){lessonKey=el.dataset.key;businessId=el.dataset.business||null;return navigate('lesson');}
    if(action==='help'){helpKey=crypto.randomUUID();return navigate('support');}
    if(action==='copy-prompt'){try{await navigator.clipboard.writeText(host.querySelector('#bp-website-prompt').textContent);message('Website prompt copied.');}catch{message('Select the prompt text and copy it.');}return;}
    if(action==='calendar'){const p=timelineRows().find(x=>x.id===el.dataset.calendarId);if(!p)return;const [s,end]=datePair(p.date);const title=p.title.replace(/[\r\n,;]/g,' ');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Fundhub//Blueprint reviews//EN','BEGIN:VEVENT','UID:blueprint-'+crypto.randomUUID()+'@fundhub.ai','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z','DTSTART;VALUE=DATE:'+s,'DTEND;VALUE=DATE:'+end,'SUMMARY:Blueprint review - '+title,'END:VEVENT','END:VCALENDAR',''].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/calendar'}));const a=document.createElement('a');a.href=url;a.download='blueprint-review.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Review calendar file downloaded.');}
  });
  host.addEventListener('submit',async e=>{const form=e.target.closest('[data-bp-form]');if(!form)return;e.preventDefault();if(busy)return;const f=new FormData(form),kind=form.dataset.bpForm;
    if(kind==='mail-confirm'){if(!mailQuote||f.get('authorization')!=='on')return;busy=true;try{const result=await request('/api/blueprint/letter-mailing',{method:'POST',body:JSON.stringify({action:'confirm',orderId:mailQuote.orderId,quoteVersion:mailQuote.quoteVersion,paymentOptionId:f.get('paymentOptionId'),authorization:true,idempotencyKey:mailQuote.orderId})});mailOrder=result.order||result;mailQuote=null;render();}catch(err){failed(form,err.message);}finally{busy=false;}return;}
    if(kind==='bureau-response'){busy=true;const submit=form.querySelector('button');submit.disabled=true;try{const body=new FormData();body.append('kind','bureau_response');body.append('subtype','other');for(const file of form.elements.files.files)body.append('files',file);await request('/api/documents-upload',{method:'POST',body,headers:headers(false)});data=await request('/api/blueprint/plan');notice='Response received. The existing document reader will validate it before the next step is reviewed.';render();}catch(err){failed(form,err.message);}finally{busy=false;submit.disabled=false;}return;}
    if(kind==='setup'){const payload={action:'save_settings'};if(setupStep===0)payload.hasExistingBusiness=f.get('existing')==='yes';if(setupStep===1)payload.targetBusinessCount=Number(f.get('count'));if(setupStep===2){payload.homeState=f.get('homeState');payload.postalCode=f.get('postalCode');payload.started=true;}if(await save(payload)){if(setupStep<2){setupStep++;render();}else navigate('today');}return;}
    if(kind==='business'){const id=businessId||newBusinessId||(newBusinessId=crypto.randomUUID());const record={id,name:String(f.get('name')||'').trim(),activity:String(f.get('activity')||'').trim(),formationState:f.get('formationState'),operatingState:f.get('operatingState')||null,website:String(f.get('website')||'').trim()||null,formationStatus:f.get('formationStatus'),formationDate:f.get('formationDate')||null,ownershipSince:f.get('ownershipSince')||null,operatingSince:f.get('operatingSince')||null};const linked=(plans().existingBusinesses||[]).find(x=>x.id===f.get('businessId'));record.businessId=linked?.id||null;record.entityId=linked?.entityId||null;if(linked&&record.formationStatus!=='reported_formed')return failed(form,'An existing business must keep its actual formed status. Confirm its formation date before saving.');if(!record.name||!record.activity)return failed(form,'Add the name and actual business activity.');if(record.formationStatus==='planned'&&(record.formationDate||record.ownershipSince||record.operatingSince))return failed(form,'A planned business has no actual dates yet. Change its status only if it has really been formed.');if(await save({action:'save_business',business:record})){businessId=id;newBusinessId=null;render();}return;}
    if(kind==='bank-readiness'){const b=currentBusiness();if(!b)return failed(form,'Choose a business first.');if(await save({action:'save_business',business:{id:b.id,bankPreparation:{documentsReady:f.get('documentsReady')==='on',accountOpeningIssue:f.get('accountOpeningIssue')==='on'}}}))render();return;}
    if(kind==='bank-relationship'){const b=currentBusiness();if(!b)return failed(form,'Choose a business first.');const id=bankRelationshipId||crypto.randomUUID();const cents=v=>v===''?null:Math.round(Number(v)*100);const row={id,bankName:String(f.get('bankName')||'').trim(),accountType:f.get('accountType'),status:f.get('status'),plannedOpenOn:f.get('plannedOpenOn')||null,openedOn:f.get('openedOn')||null,depositPlanCents:cents(f.get('depositPlan')),depositReportedCents:cents(f.get('depositReported')),depositedOn:f.get('depositedOn')||null,seasoningDays:f.get('seasoningDays')===''?null:Number(f.get('seasoningDays')),nextReviewOn:f.get('nextReviewOn')||null};const rows=(b.bankPreparation?.relationships||[]).filter(x=>x.id!==id);rows.push(row);if(await save({action:'save_business',business:{id:b.id,bankPreparation:{relationships:rows}}})){bankRelationshipId=null;bankReferenceDraft=null;render();}return;}
    if(kind==='budget'){const toCents=value=>value===''?null:Math.round(Number(value)*100);const cash=toCents(f.get('cash')),income=toCents(f.get('income')),buffer=toCents(f.get('buffer')),payoff=toCents(f.get('payoffReserve'));if([cash,income,buffer,payoff].some(v=>v!=null&&(!Number.isSafeInteger(v)||v<0)))return failed(form,'Use valid amounts of zero or more, or leave unknown values blank.');if(await save({action:'save_settings',availableCashCents:cash,monthlyIncomeCents:income,cashBufferCents:buffer,oneTimePayoffCents:payoff}))render();return;}
    if(kind==='payoff-settings'){const p=plans().payoffPlan||{},monthly=f.get('monthlyBudget');if(await save({action:'save_payoff_plan',strategy:f.get('strategy'),monthlyBudgetCents:monthly===''?null:Math.round(Number(monthly)*100),debts:p.debts||[]}))render();return;}
    if(kind==='payoff-debt'){if(f.get('balance')==='')return failed(form,'Add the current balance from your statement.');const p=plans().payoffPlan||{},id=payoffDebtId||newPayoffDebtId||(newPayoffDebtId=crypto.randomUUID()),row={id,label:String(f.get('label')||'').trim(),balanceCents:Math.round(Number(f.get('balance'))*100),aprBps:f.get('apr')===''?null:Math.round(Number(f.get('apr'))*100),minimumPaymentCents:f.get('minimum')===''?null:Math.round(Number(f.get('minimum'))*100)};if(await save({action:'save_payoff_plan',strategy:p.strategy||'snowball',monthlyBudgetCents:p.monthlyBudgetCents??null,debts:[...(p.debts||[]).filter(d=>d.id!==id),row]})){payoffDebtId=null;newPayoffDebtId=null;render();}return;}
    if(kind==='step'){if(['formation','ein','business_profile','business_website','business_listings','bank_opening','bank_deposit','business_credit','merchant_tools'].includes(lessonKey)&&!businessId)return failed(form,'Choose the business this step belongs to first.');const payload={action:'save_step',stepKey:lessonKey,businessPlanId:businessId,status:f.get('status'),note:String(f.get('note')||'').trim(),targetDate:f.get('targetDate')||null};if(await save(payload))render();return;}
    if(kind==='saved-evidence'){if(await save({action:'attach_evidence',businessId:form.dataset.business,kind:form.dataset.kind,documentId:f.get('documentId')}))render();return;}
    if(kind==='evidence'){const key=form.dataset.business+':'+form.dataset.kind;let documentId=pendingEvidence.get(key)||null;const file=form.elements.file.files[0];if(!documentId&&!file)return;busy=true;const submit=form.querySelector('button[type=submit]');submit.disabled=true;submit.textContent=documentId?'Attaching saved document…':'Uploading…';try{if(!documentId){const body=new FormData();body.append('kind','client_upload');body.append('subtype',form.dataset.subtype);const plan=businesses().find(b=>b.id===form.dataset.business);if(plan?.entityId)body.append('entity_id',plan.entityId);body.append('files',file);const uploaded=await request('/api/documents-upload',{method:'POST',body,headers:headers(false)});documentId=uploaded.documents?.[0]?.id||uploaded.results?.[0]?.document?.id||uploaded.results?.[0]?.id;if(!documentId)throw new Error('The upload did not return a saved document. Please retry before attaching it.');pendingEvidence.set(key,documentId);}await request('/api/blueprint/business-plans',{method:'POST',body:JSON.stringify({action:'attach_evidence',businessId:form.dataset.business,kind:form.dataset.kind,documentId})});pendingEvidence.delete(key);data=await request('/api/blueprint/plan');notice='Document uploaded and attached. Its review status comes from the saved record.';render();}catch(err){failed(form,(documentId?'The file is stored, but it could not be attached to this business. Retry this step to attach the stored file. ':'')+err.message);}finally{busy=false;submit.disabled=false;submit.textContent=documentId&&pendingEvidence.has(key)?'Retry attaching stored document':'Upload document';}return;}
    if(kind==='help'){const text=String(f.get('message')||'').trim();if(!text)return;busy=true;try{helpKey ||= crypto.randomUUID();await request('/api/chat/portal-message',{method:'POST',body:JSON.stringify({body:text,channel:'sms',idempotency_key:helpKey})});helpKey=null;form.reset();message('Your message is saved in your Fundhub conversation.');}catch(err){failed(form,err.message);}finally{busy=false;}return;}
  });
  request('/api/auth/session').then(session=>{if(session.principal==='client'||session.staff?.role==='client')return load();host.hidden=true;},()=>{host.hidden=true;});
})();
